// Recibe lo que manda la app y arma el pedido para Gemini.
const raw = $json.body;
const d = typeof raw === 'string' ? JSON.parse(raw) : (raw || {});

const productos = (d.productos || [])
  .map(p => `- id: ${p.id} | ${p.nombre} | se vende por ${p.unidad} | precio actual $${p.precio}`)
  .join('\n');

let instrucciones;
if (d.tipo === 'gasto') {
  instrucciones = `Sos un asistente que registra GASTOS de un negocio de pastas frescas en Argentina.
Hoy es ${d.hoy}. Interpretá la frase y devolvé SOLO este JSON:
{"fecha":"YYYY-MM-DD","monto":number,"categoria":string,"descripcion":string}
- categoria tiene que ser EXACTAMENTE una de: ${JSON.stringify(d.categorias)}. Si no encaja, "Otros".
- "ayer"/"anteayer" se calculan desde hoy. Si no dice fecha, hoy.
- "45 mil" = 45000, "1 palo" = 1000000, "lucas" = miles.
- descripcion: corta y clara, en castellano, sin el monto.`;
} else {
  instrucciones = `Sos un asistente que registra VENTAS de un negocio de pastas frescas en Argentina.
Hoy es ${d.hoy}. Productos cargados:
${productos}

Interpretá la frase y devolvé SOLO este JSON:
{"fecha":"YYYY-MM-DD","cliente":string,"metodoPago":string|null,"items":[{"productoId":string,"cantidad":number,"precioUnit":number|null}]}
- productoId tiene que ser uno de los id de la lista. Elegí el producto más parecido a lo que se dijo. Si no hay ninguno parecido, no lo incluyas.
- cantidad en la unidad de venta del producto: "medio kilo" = 0.5, "kilo y medio" = 1.5, "500 gramos" = 0.5 si se vende por kg, "una docena" = 12 si se vende por unidad.
- precioUnit es el precio POR UNIDAD de venta. Si dicen el total ("3 kilos por 27 mil"), dividilo por la cantidad. Si no dicen precio, null.
- "9 mil" = 9000, "lucas" = miles.
- metodoPago tiene que ser EXACTAMENTE uno de: ${JSON.stringify(d.metodosPago)} o null si no lo dice. "fiado" = "Cuenta corriente", "MP" = "Mercado Pago".
- cliente: el nombre si lo dice, si no "".
- "ayer"/"anteayer" se calculan desde hoy. Si no dice fecha, hoy.`;
}

return [{
  json: {
    tipo: d.tipo,
    gemini: {
      contents: [{ role: 'user', parts: [{ text: instrucciones + '\n\nFrase: "' + d.texto + '"' }] }],
      generationConfig: { temperature: 0, responseMimeType: 'application/json' }
    }
  }
}];

// Saca el JSON de la respuesta de Gemini.
const texto = $json.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
let datos;
try {
  datos = JSON.parse(texto.replace(/```json|```/g, '').trim());
} catch (e) {
  datos = {};
}
return [{ json: datos }];
